<script setup lang="ts">
import type { usePlayer } from '../../composables/usePlayer'
import { TabsRoot, TabsList, TabsTrigger, TabsContent } from 'reka-ui'
import { getMessage, pseudocode } from '../../engine'
import { useLabStore } from '../../stores/lab'
defineProps<{ player: ReturnType<typeof usePlayer> }>()
const lab = useLabStore()
const tab = ref('explanation')
const code = computed(() => pseudocode[lab.step?.code.algo ?? ''] ?? [])
const counters = [['comparisons', 'Comparações'], ['rotations', 'Rotações'], ['recolorings', 'Recolorações'], ['heightUpdates', 'Alturas atualizadas'], ['visits', 'Visitas']] as const
const explanations: Record<string, string> = { compare: 'A comparação decide o caminho: uma chave menor segue à esquerda; uma maior, à direita. A árvore mantém essa ordem em todas as etapas.', 'rotate-pre': 'O filho destacado sobe e o pivô desce. A subárvore do meio troca de pai. A rotação custa O(1) e preserva a ordem in-ordem.', rotate: 'Observe os identificadores: os nós mudam de posição, mas mantêm suas chaves. Rotacionar reorganiza os ponteiros sem mudar a ordem crescente.', recolor: 'A cor registra as propriedades da Rubro-Negra. A recoloração não muda a posição dos nós nem a ordem das chaves.', transplant: 'O sucessor é movido por transplante. Ele mantém seu identificador e assume a posição do nó removido; sua antiga subárvore continua conectada.', update: 'Altura é o número de arestas até a folha mais distante. Uma folha tem altura 0; NIL tem altura −1. FB = altura esquerda − altura direita.', 'extra-black': 'Ao remover um nó preto, um caminho pode perder um preto. O preto extra marca essa diferença até que o conserto restaure a altura negra.', visit: 'Cada nó é visitado uma vez. Todo percurso custa Θ(n); a ordem escolhida determina quando cada chave entra na saída.' }
</script>
<template>
  <div class="details"><LabPlayerBar :player="player" compact /><TabsRoot v-model="tab"><TabsList class="detail-tabs" aria-label="Detalhes do passo"><TabsTrigger value="explanation">Explicação</TabsTrigger><TabsTrigger value="code">Código</TabsTrigger><TabsTrigger value="cost">Custo</TabsTrigger></TabsList><TabsContent value="explanation"><p>{{ lab.step ? getMessage(lab.step.msg) : 'Crie uma sequência para acompanhar as decisões do algoritmo.' }}</p><p class="detail-description">{{ explanations[lab.step?.kind ?? ''] ?? 'O motor produz este passo a partir da sequência. Avance devagar, compare o estado anterior e observe quais relações entre nós mudam.' }}</p><NuxtLink to="/glossario" class="glossary-link">Consultar o glossário<Icon name="lucide:arrow-up-right" /></NuxtLink></TabsContent><TabsContent value="code"><ol class="pseudocode"><li v-for="line in code" :key="line.n" :class="{ current: line.n === lab.step?.code.line }"><span>{{ line.n }}</span>{{ line.text }}</li></ol><p v-if="!code.length">O código aparece ao iniciar uma operação.</p></TabsContent><TabsContent value="cost"><table><thead><tr><th>Medida</th><th>Operação</th><th>Sequência</th></tr></thead><tbody><tr v-for="[key, label] in counters" :key="key"><th>{{ label }}</th><td>{{ lab.operationCost?.[key] ?? 0 }}</td><td>{{ lab.totalCost[key] }}</td></tr></tbody></table><p class="detail-description">Uma rotação dupla conta como duas rotações. Uma recoloração conta cada nó cuja cor mudou.</p></TabsContent></TabsRoot></div>
</template>
<style scoped>.details { min-height: 300px; }.detail-tabs { display: flex; gap: 8px; padding: 10px 0 14px; }.detail-tabs button { flex: 1; min-height: 48px; font-size: 13px; border-bottom: 2px solid transparent; color: var(--muted); }.detail-tabs button[data-state='active'] { color: var(--accent); border-color: var(--accent); }.details p { font-size: 15px; line-height: 1.6; margin: 12px 0; }.detail-description { color: var(--muted); }.glossary-link { min-height: 48px; color: var(--accent); display: flex; align-items: center; gap: 8px; font-size: 13px; }.pseudocode { margin: 10px 0; display: grid; gap: 6px; }.pseudocode li { display: flex; gap: 12px; padding: 10px 8px; font: 12px/1.6 'JetBrains Mono', monospace; border-radius: 8px; }.pseudocode li > span { color: var(--muted); }.pseudocode .current { background: var(--surface-3); border-left: 2px solid var(--accent); }table { width: 100%; border-collapse: collapse; font-size: 13px; }th { text-align: left; font-weight: 500; }td { text-align: center; font: 13px 'JetBrains Mono', monospace; }th,td { padding: 12px 5px; border-bottom: 1px solid var(--border); }thead { color: var(--muted); }</style>
